"""Actual product adapter + real Pixi GC/WebGL, authored 4K debug model.
Checks active retention, stale handle recovery, unused collection and disposal.
No GC disabling or fake GL. Model artwork is not accepted by this test.
"""
import base64,io,json,os,time,zipfile,datetime,hashlib,traceback
from pathlib import Path
os.environ.setdefault('COMPANION_LIVE2D_RUNTIME','/workspace/.live2d/runtime')
from playwright.sync_api import sync_playwright
from test_character_http import CharacterHTTPTests
ROOT=Path(__file__).resolve().parents[1];OUT=Path('/workspace/dist/live2d-texture-lifecycle');OUT.mkdir(parents=True,exist_ok=True)
HOOK='''(()=>{let runtime;Object.defineProperty(window,'CompanionLive2DRuntime',{configurable:true,get(){return runtime;},set(value){runtime=value;const init=value.PIXI.Application.prototype.init;value.PIXI.Application.prototype.init=async function(options){await init.call(this,options);window.__actualPixiApps??=[];window.__actualPixiApps.push(this);};}});})()'''
PIXELS='''()=>{const app=__actualPixiApps.find(app=>app.stage?.children?.some(c=>c.internalModel)),gl=app.renderer.gl;app.renderer.render(app.stage);const pixels=new Uint8Array(gl.drawingBufferWidth*gl.drawingBufferHeight*4);gl.readPixels(0,0,gl.drawingBufferWidth,gl.drawingBufferHeight,gl.RGBA,gl.UNSIGNED_BYTE,pixels);let alpha=0,colored=0;for(let i=0;i<pixels.length;i+=4){if(pixels[i+3]>8){alpha++;if(pixels[i]+pixels[i+1]+pixels[i+2]<740)colored++;}}return {alpha,colored,error:gl.getError()};}'''
def bundle():
 folder=Path(os.environ.get('COMPANION_GC_EXPORT',str(ROOT/'.build/original-character-rig-r3/export-cli')));buffer=io.BytesIO()
 with zipfile.ZipFile(buffer,'w',zipfile.ZIP_DEFLATED)as z:
  for path in folder.rglob('*'):
   if path.is_file()and(path.name.endswith(('.model3.json','.moc3','.png','.motion3.json','.exp3.json','.physics3.json','.cdi3.json','.pose3.json'))):z.write(path,path.relative_to(folder).as_posix())
 return buffer.getvalue()
def main():
 f=CharacterHTTPTests('test_new_identity_has_separate_memories_chat_tasks_and_personality');f.setUp();report={'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'RUNNING','scope':'actual product adapter, owner Cubism/Pixi, original authored 4096 atlas debug export; real WebGL GC and wall-clock endurance','artwork_accepted':False,'gc_disabled':False,'checks':{},'sources':{name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest()for name in ['frontend/live2d-renderer.mjs','app/static/live2d-renderer.js','app/static/scene-controller.js']}};errors=[]
 try:
  with sync_playwright()as pw:
   browser=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']);context=browser.new_context(viewport={'width':1200,'height':900},record_video_dir=str(OUT/'video'),record_video_size={'width':1200,'height':900});page=context.new_page();page.add_init_script(HOOK);page.on('pageerror',lambda e:errors.append(str(e)));base='http://127.0.0.1:'+str(f.server.server_port);page.goto(base);page.wait_for_function('()=>CompanionApp.core.get().state!==null');role=page.evaluate('()=>CompanionApp.core.scope().character_id');data=bundle();headers={'X-Companion':'local-app'};r=page.request.post(base+'/api/characters/assets/import',data={'character_id':role,'format':'live2d','model':{'filename':'authored-4k-debug.zip','data_base64':base64.b64encode(data).decode()}},headers=headers);assert r.ok,r.text();asset=r.json()['asset'];r=page.request.post(base+'/api/characters/assets/activate',data={'character_id':role,'asset_id':asset['id']},headers=headers);assert r.ok,r.text();page.evaluate('()=>CompanionApp.core.refresh(true)');page.wait_for_function('()=>CompanionApp.scene.ready&&CompanionApp.scene.getDiagnostics().coreEvaluations>2',timeout=60000);initial=page.evaluate(PIXELS);assert initial['error']==0 and initial['colored']>1000,initial;page.screenshot(path=str(OUT/'01-initial-4k.png'));report['checks']['actual_4k_authored_texture_is_visible']='passed'
   # Test-only clock aging accelerates exactly the same GC predicate. The app
   # refreshes active resources via Pixi prerender; an unreferenced real texture
   # must still be collected by the same enabled GC.
   accelerated=page.evaluate('''async()=>{const app=__actualPixiApps.find(app=>app.stage?.children?.some(c=>c.internalModel)),renderer=app.renderer,gl=renderer.gl,model=app.stage.children.find(c=>c.internalModel),source=model.textures[0].source;const originalMax=renderer.gc.maxUnusedTime;source._gcLastUsed=performance.now()-1000;const aged=source._gcLastUsed;const start=CompanionApp.scene.getStats().frames;while(CompanionApp.scene.getStats().frames<start+3)await new Promise(requestAnimationFrame);const afterRender=source._gcLastUsed;const canvas=document.createElement('canvas');canvas.width=canvas.height=16;const unused=CompanionLive2DRuntime.PIXI.Texture.from(canvas),unusedGpu=renderer.texture.getGlSource(unused.source);unused.source.autoGarbageCollect=true;unused.source._gcLastUsed=performance.now()-1000;renderer.gc.maxUnusedTime=500;const activeHandle=model.cachedGlTextures[0];renderer.gc.run();const result={gcEnabled:renderer.gc.enabled,aged,afterRender,lastUsedRefreshed:afterRender>aged,activeHandleAlive:gl.isTexture(activeHandle),unusedHandleAlive:gl.isTexture(unusedGpu.texture),width:source.width,height:source.height};renderer.gc.maxUnusedTime=originalMax;unused.destroy(true);window.__retainedActive={source,handle:activeHandle,app};return result;}''');assert accelerated['gcEnabled']and accelerated['lastUsedRefreshed']and accelerated['activeHandleAlive']and not accelerated['unusedHandleAlive'],accelerated;assert max(accelerated['width'],accelerated['height'])==4096;report['accelerated_gc']=accelerated;report['checks']['active_4k_texture_refreshed_unused_real_texture_collected']='passed';assert page.evaluate(PIXELS)['error']==0;report['checks']['no_deleted_handle_binding_after_real_gc']='passed'
   recovered=page.evaluate('''async()=>{const app=__retainedActive.app,model=app.stage.children.find(c=>c.internalModel),source=model.textures[0].source,gl=app.renderer.gl,old=model.cachedGlTextures[0];source.unload();const dead=!gl.isTexture(old),start=CompanionApp.scene.getStats().frames;while(CompanionApp.scene.getStats().frames<start+3)await new Promise(requestAnimationFrame);return {oldDeleted:dead,newAlive:gl.isTexture(model.cachedGlTextures[0]),newHandle:model.cachedGlTextures[0]!==old,error:gl.getError()};}''');assert recovered['oldDeleted']and recovered['newAlive']and recovered['newHandle']and recovered['error']==0,recovered;assert page.evaluate(PIXELS)['colored']>1000;report['stale_handle_recovery']=recovered;report['checks']['unloaded_texture_reuploads_and_replaces_stale_wrapper_handle']='passed'
   # Keep default real 60s idle policy/30s collection frequency. Wait >60s with
   # normal app RAF, collecting real samples without synthetic frame stepping.
   start=time.monotonic();samples=[]
   while time.monotonic()-start<66:
    page.wait_for_timeout(1000)
    elapsed=time.monotonic()-start
    if not samples or elapsed-samples[-1]['wall_seconds']>=9:
     pixels=page.evaluate(PIXELS);samples.append({'wall_seconds':round(elapsed,3),'frames':page.evaluate('()=>CompanionApp.scene.getStats().frames'),**pixels});assert pixels['error']==0 and pixels['colored']>1000,samples[-1]
   report['wall_clock_samples']=samples;report['wall_clock_seconds']=round(time.monotonic()-start,3);report['checks']['default_gc_policy_over_60_seconds_preserves_real_visible_pixels']='passed';page.screenshot(path=str(OUT/'02-after-wall-clock.png'));page.evaluate('()=>CompanionApp.pause()');page.wait_for_timeout(200);released=page.evaluate('()=>({canvasCount:document.querySelectorAll("#character-canvas canvas").length,textureAlive:__retainedActive.app.renderer?.gl?.isTexture(__retainedActive.handle)??false})');assert released['canvasCount']==0 and not released['textureAlive'],released;report['checks']['pause_disposes_canvas_and_gpu_texture']='passed';page.evaluate('()=>CompanionApp.scene.setVisible(true)');page.wait_for_function('()=>CompanionApp.scene.ready&&CompanionApp.scene.getDiagnostics().coreEvaluations>2',timeout=60000);assert page.evaluate(PIXELS)['colored']>1000;report['checks']['restore_recreates_valid_model_and_texture']='passed';page.screenshot(path=str(OUT/'03-restored.png'));assert not errors,errors;report['checks']['javascript_runtime']='passed';context.close();browser.close();report['status']='passed'
 except Exception as e:report['status']='failed';report['error']=str(e);report['traceback']=traceback.format_exc();raise
 finally:report['page_errors']=errors;(ROOT/'review/live2d-product-texture-lifecycle.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));f.tearDown()
 print(json.dumps({'status':report['status'],'checks':report['checks'],'accelerated_gc':report.get('accelerated_gc'),'wall_clock_seconds':report.get('wall_clock_seconds')},ensure_ascii=False))
if __name__=='__main__':main()
